practice.starter:
def cooldown(rate, per, times):
    # your code
    pass

practice.solution:
def cooldown(rate, per, times):
    tokens = rate
    window = 0.0
    out = []
    for t in times:
        if t > window + per:
            tokens = rate
        if tokens == rate:
            window = t
        tokens -= 1
        if tokens < 0:
            tokens = 0
            out.append(round(per - (t - window), 1))
        else:
            out.append(None)
    return out

