def button_emojis(buttons):
    used = [b for b in buttons if b != '']
    out = []
    n = 0
    for b in buttons:
        if b != '':
            out.append(b)
        else:
            letter = chr(65 + n)
            while letter in used:
                n += 1
                letter = chr(65 + n)
            out.append(letter)
            n += 1
    return out

