    # your code
    pass

practice.solution:
def page_after(page, pages, reaction):
    if reaction == 'first':
        return 0
    if reaction == 'prev':
        return max(0, page - 1)
    if reaction == 'next':
        return min(pages - 1, page + 1)
    if reaction == 'last':
        return pages - 1
    return page

