def ask(fields, answers):
    values = []
    missing = []
    for i in range(len(fields)):
        name, required = fields[i]
        a = answers[i] if i < len(answers) else ''
        values.append([name, a])
        if required and a == '':
            missing.append(name)
    return [values, missing]

